"""Version ranges, as written in manifests and in index dependencies (docs/ranges.md)."""

import re

from pinset.errors import RangeError, VersionError
from pinset.version import Version

OPERATORS = ("<=", ">=", "<", ">", "=", "^", "~")
WILD = ("x", "X", "*")
_NUM = re.compile(r"0|[1-9][0-9]*")
_SPACE = " \t"
_SPLIT = re.compile(r"[ \t]+")


def _low(M, m, p):
    return Version(M, m, p, ("0",))


class _Alt:
    """One alternative: conditions that all must hold, plus releases that carry a prerelease."""

    def __init__(self):
        self.conds = []  # (op, Version) or ("none", None)
        self.carry = set()

    def add(self, op, version, carries=False):
        self.conds.append((op, version))
        if carries and version.is_prerelease():
            self.carry.add(version.release)

    def test(self, v: Version) -> bool:
        for op, ref in self.conds:
            if op == "none":
                return False
            if op == "=":
                ok = v == ref
            elif op == ">=":
                ok = v >= ref
            elif op == ">":
                ok = v > ref
            elif op == "<=":
                ok = v <= ref
            else:
                ok = v < ref
            if not ok:
                return False
        if v.is_prerelease() and v.release not in self.carry:
            return False
        return True


class Range:
    def __init__(self, text: str, alts, exact: bool):
        self.text = text
        self._alts = alts
        self._exact = exact

    def test(self, version: Version) -> bool:
        """True when `version` satisfies the range."""
        return any(a.test(version) for a in self._alts)

    def is_exact(self) -> bool:
        """True for a range that names one version (docs/resolve.md, section 4)."""
        return self._exact

    def __str__(self):
        return self.text


def _partial(text: str):
    """Returns (M, m, p, full_version_or_None); wildcards are None."""
    if "+" in text or "-" in text:
        try:
            v = Version.parse(text)
        except VersionError as e:
            raise RangeError("bad-version", str(e)) from None
        return v.major, v.minor, v.patch, v
    parts = text.split(".")
    if len(parts) > 3:
        raise RangeError("bad-version", f"too many parts in {text!r}")
    nums = []
    wild = False
    for part in parts:
        if part in WILD:
            wild = True
            nums.append(None)
        elif _NUM.fullmatch(part):
            if wild:
                raise RangeError("bad-version", f"a number after a wildcard in {text!r}")
            nums.append(int(part))
        else:
            raise RangeError("bad-version", f"bad part {part!r} in {text!r}")
    nums += [None] * (3 - len(nums))
    full = Version(*nums) if None not in nums else None
    return nums[0], nums[1], nums[2], full


def _upper(M, m, p):
    """Exclusive upper bound of the block a partial names (None for the whole range)."""
    if M is None:
        return None
    if m is None:
        return _low(M + 1, 0, 0)
    if p is None:
        return _low(M, m + 1, 0)
    return None


def _comparator(alt: _Alt, op: str, M, m, p, full):
    if op == "^" or op == "~":
        if M is None:
            return
        if op == "~":
            hi = _low(M + 1, 0, 0) if m is None else _low(M, m + 1, 0)
        elif M != 0:
            hi = _low(M + 1, 0, 0)
        elif m is None:
            hi = _low(1, 0, 0)
        elif m != 0:
            hi = _low(0, m + 1, 0)
        elif p is None:
            hi = _low(0, 1, 0)
        else:
            hi = _low(0, 0, p + 1)
        alt.add(">=", full or Version(M, m or 0, p or 0), True)
        alt.add("<", hi)
        return
    if full is not None:
        alt.add(op or "=", full, True)
        return
    if M is None:
        if op in ("<", ">"):
            alt.add("none", None)
        return
    lo = Version(M, m or 0, p or 0)
    hi = _upper(M, m, p)
    if op in ("", "="):
        alt.add(">=", lo)
        alt.add("<", hi)
    elif op == ">=":
        alt.add(">=", lo)
    elif op == ">":
        alt.add(">=", Version(hi.major, hi.minor, hi.patch))
    elif op == "<":
        alt.add("<", _low(M, m or 0, p or 0))
    else:  # <=
        alt.add("<", hi)


def _hyphen(lo_text: str, hi_text: str) -> _Alt:
    alt = _Alt()
    M, m, p, full = _partial(lo_text)
    M2, m2, p2, full2 = _partial(hi_text)
    if M is not None:
        alt.add(">=", full or Version(M, m or 0, p or 0), True)
    if M2 is None:
        alt.add("none", None)
    elif full2 is not None:
        alt.add("<=", full2, True)
    else:
        alt.add("<", _upper(M2, m2, p2))
    if M2 is None:
        alt.conds.pop()  # a wildcard major has no upper bound
    return alt


def _split_op(token: str):
    for op in OPERATORS:
        if token.startswith(op):
            return op, token[len(op):]
    return "", token


def parse_range(text: str) -> Range:
    if not isinstance(text, str):
        raise RangeError("bad-range", f"a range is a string, not {type(text).__name__}")
    if not text.strip(_SPACE):
        raise RangeError("bad-range", "empty range")
    raw_alts = text.split("||")
    token_lists = []
    for raw in raw_alts:
        body = raw.strip(_SPACE)
        if not body:
            raise RangeError("bad-range", "empty alternative")
        token_lists.append(_SPLIT.split(body))
    # Shape checks for the whole range come before any version check.
    shapes = []
    for tokens in token_lists:
        if "-" in tokens:
            if len(tokens) != 3 or tokens[1] != "-":
                raise RangeError("bad-range", "misplaced '-'")
            if _split_op(tokens[0])[0] or _split_op(tokens[2])[0]:
                raise RangeError("bad-range", "operator in a hyphen range")
            shapes.append(("hyphen", tokens[0], tokens[2]))
        else:
            items = []
            for t in tokens:
                op, rest = _split_op(t)
                if not rest or not (rest[0].isascii() and rest[0].isdigit() or rest[0] in WILD):
                    raise RangeError("bad-range", f"cannot read {t!r}")
                items.append((op, rest))
            shapes.append(("set", items))
    alts = []
    exact = False
    for shape in shapes:
        if shape[0] == "hyphen":
            alts.append(_hyphen(shape[1], shape[2]))
        else:
            alt = _Alt()
            parsed = [(op, _partial(rest)) for op, rest in shape[1]]
            for op, (M, m, p, full) in parsed:
                _comparator(alt, op, M, m, p, full)
            alts.append(alt)
            if len(parsed) == 1 and parsed[0][0] in ("", "=") and parsed[0][1][3] is not None:
                exact = True
    return Range(text, alts, exact and len(alts) == 1)
